    ("EMAIL_PROVIDER", "Identity / polyrob / local profile", "`auto`", "Which transport backs the agent's email: `smtp` \\"),
    ("AGENTMAIL_API_KEY", "Identity / polyrob / local profile", "unset", "AgentMail (api.agentmail.to) API key. Its presence makes `agentmail` the `auto` provider: the agent provisions its OWN inbox idempotently on first run (address persisted to `<data_home>/agent_mail.json`) — no SMTP/IMAP setup."),
    ("POLYROB_AGENT_EMAIL", "Identity / polyrob / local profile", "unset", "Explicit override for the agent's OWN sender address (distinct from `POLYROB_OWNER_EMAIL`, an outbound target). Unset: the provisioned managed inbox, else `GMAIL_EMAIL`."),
    ("WHATSAPP_SURFACE_ENABLED", "Identity / polyrob / local profile", "OFF (**ON for `polyrob whatsapp`**)", "WhatsApp Cloud API webhook surface enable flag."),
