    ("SLACK_BOT_TOKEN", "Identity / polyrob / local profile", "unset (secret, masked)", "Slack surface credentials: bot token (`xoxb-`) + Socket-Mode app token (`xapp-`); both required or `polyrob slack` refuses to start."),
    ("SLACK_APP_TOKEN", "Identity / polyrob / local profile", "unset (secret, masked)", "Slack surface credentials: bot token (`xoxb-`) + Socket-Mode app token (`xapp-`); both required or `polyrob slack` refuses to start."),
