    ("SIGNAL_SEND_MIN_INTERVAL_SEC", "Identity / polyrob / local profile", "`1.0`", "Minimum seconds between Signal sends (send throttle)."),
    ("TWITTER_BOT_USER_ID", "Identity / polyrob / local profile", "unset", "The bot's own X numeric user id for the X DM surface; unset = discovered via `get_me()` at startup (one API call saved when set)."),
