    ("DEV_RAIL_SCRIPT", "Identity / polyrob / local profile", "unset (a default path in the install tree)", "Absolute path to the Telegram `/dev` rail's inject script. The rail is OFF unless this resolves to a real file, so a deployment that ships no such script has no `/dev`."),
    ("CHAT_INTENT_CLASSIFIER", "Identity / polyrob / local profile", "OFF", "Enable the chat-surface intent classifier (pre-routing intent detection on inbound chat messages)."),
    ("OUTBOUND_QUEUE_ENABLED", "Identity / polyrob / local profile", "OFF", "Durable outbound send queue (retry + dead-letter) behind `publish()`'s PRIMARY reply routing (direct-send vs. queued-with-retry for a locally-subscribed surface); OFF = direct legacy sends. Streaming deltas are always best-effort (never queued). Since 2026-08-30 the queue/dispat…"),
    ("VOICE_TRANSCRIPTION_REQUIRED", "Identity / polyrob / local profile", "OFF", "Make a missing faster-whisper engine a startup ERROR instead of a WARN (most deploys degrade gracefully: voice refused with a notice)."),
    ("INTERACTIVE_TOOL_IDS", "Identity / polyrob / local profile", "unset", "Explicit comma-list override of the interactive-owner chat toolset; unset derives it (supervised: the `owner_interactive` toolset; effective autonomous mode: the full autonomous grant + compute tools)."),
    ("SELF_CONTEXT_WRITABLE", "Identity / polyrob / local profile", "OFF (**ON under POLYROB_LOCAL + AUTONOMY_ENABLED**)", "Agent can write its evolving SELF identity doc."),
